func TestNovelWatchBehavior(t *testing.T) {
	t.Run("first run establishes baseline", func(t *testing.T) {
		cur := watchSnapshot{Term: "x", Trials: map[string]watchEntry{
			"NCT1": {Status: "RECRUITING", LastUpdate: "2026-01-01"},
		}}
		v := diffWatch("x", watchSnapshot{}, false, cur)
		if !v.FirstRun || v.Tracked != 1 {
			t.Fatalf("first run: got FirstRun=%v Tracked=%d", v.FirstRun, v.Tracked)
		}
		if len(v.New)+len(v.Changed)+len(v.Terminated) != 0 {
			t.Fatalf("first run should report no changes, got %+v", v)
		}
	})

	t.Run("detects new, changed, terminated", func(t *testing.T) {
		prev := watchSnapshot{Term: "x", Trials: map[string]watchEntry{
			"NCT1": {Status: "RECRUITING", LastUpdate: "2026-01-01"},
			"NCT2": {Status: "RECRUITING", LastUpdate: "2026-01-01"},
		}}
		cur := watchSnapshot{Term: "x", Trials: map[string]watchEntry{
			"NCT1": {Status: "RECRUITING", LastUpdate: "2026-02-01"}, // changed
			"NCT2": {Status: "TERMINATED", LastUpdate: "2026-02-01"}, // terminated
			"NCT3": {Status: "RECRUITING", LastUpdate: "2026-02-01"}, // new
		}}
		v := diffWatch("x", prev, true, cur)
		if len(v.New) != 1 || v.New[0].NCTID != "NCT3" {
			t.Errorf("new = %+v, want [NCT3]", v.New)
		}
		if len(v.Changed) != 1 || v.Changed[0].NCTID != "NCT1" {
			t.Errorf("changed = %+v, want [NCT1]", v.Changed)
		}
		if len(v.Terminated) != 1 || v.Terminated[0].NCTID != "NCT2" {
			t.Errorf("terminated = %+v, want [NCT2]", v.Terminated)
		}
	})

	t.Run("no changes", func(t *testing.T) {
		snap := watchSnapshot{Term: "x", Trials: map[string]watchEntry{
			"NCT1": {Status: "RECRUITING", LastUpdate: "2026-01-01"},
		}}
		v := diffWatch("x", snap, true, snap)
		if len(v.New)+len(v.Changed)+len(v.Terminated) != 0 {
			t.Fatalf("expected no changes, got %+v", v)
		}
		if v.Note == "" {
			t.Error("expected a 'no changes' note")
		}
	})

	t.Run("slug is filesystem-safe", func(t *testing.T) {
		if got := slugForFilename("Type 2 Diabetes!"); got != "type-2-diabetes" {
			t.Errorf("slugForFilename = %q, want %q", got, "type-2-diabetes")
		}
		if got := slugForFilename("???"); got != "term" {
			t.Errorf("empty slug fallback = %q, want %q", got, "term")
		}
	})
}
